import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"23、【剥】 坤下艮上","description":"周易阐真 - 23、【剥】 坤下艮上","frontmatter":{"title":"23、【剥】 坤下艮上","description":"周易阐真 - 23、【剥】 坤下艮上"},"headers":[],"relativePath":"zh/classics/chanzhen/024.md","filePath":"zh/classics/chanzhen/024.md"}'),s={name:"zh/classics/chanzhen/024.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：剥，剥也。柔变刚也。不利有攸往，小人长也。顺而止之，观象也。君子尚消息盈虚，天行也。</p></blockquote><h1 id="_23、【剥】-坤下艮上" tabindex="-1">23、【剥】 坤下艮上 <a class="header-anchor" href="#_23、【剥】-坤下艮上" aria-label="Permalink to “23、【剥】 坤下艮上”">​</a></h1><p>初六：剥床以足，蔑贞凶。</p><p>六二：剥床以辨，蔑贞凶。</p><p>六三：剥之，无咎。</p><p>六四：剥床以肤，凶。</p><p>六五：贯鱼以宫人宠，无不利。</p><p>上九：硕果不食。君子得舆，小人剥庐。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：山附于地，剥。上以厚下安宅。</p><p>剥者，消去也。上艮山，下坤地，是山附于地也。山本高，地本低，以山附地，去其高之有余，厚其低之不足，剥之象也。</p><p>为上者有见于此，知山不附地，则山不着实；上不厚下，则上不安居。以是剥上厚下，使在下者，皆得其所焉。盖民为邦本，本固邦宁，而在上者，亦安其所居之宅，行无为之治矣。修道之士，有才有智者，亦上也；无才无智者，亦下也。有才不恃，有智不用，剥去才智之有余，就于才智之不足，以高附低，以实居虚，则高为真高，实为真实，化假为真，止于至善之地而不迁，安居其宅，不为客气所伤矣。夫仁者，人之安宅也。剥上厚下，颠倒之间，剥即变复。复则能依于仁，生机回转，性命有赖，厚下安宅，天机毕露矣。</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>辨，音瓣。</p><p>剥者，消化也。卦德上艮止，下坤顺，阴顺生而阳止息，且卦体五阴而消一阳，阳气将尽，阴气将纯，故谓剥。此后天阴消其阳之卦，承上噬嗑而来。噬嗑者，动而必明，所以先穷理也。穷理者，穷其阴阳消长之理耳。</p><p>人秉天地阴阳五行之气而生身，有命而即有性，性命寓于一身之中矣。当人生之初，性命一家，先天后天混而为一，阴阳未分，邪正未判，圆成之象。及其成人气足，先天阳极，交于后天。一阴潜生，日复一日，年复一年，阴气渐盛，阳气渐弱，不至消尽其阳而不止，如卦体五阴而剥一阳。当此之时，阳不胜阴，其所余者，几希之阳耳。</p><p>人若不知，而犹认假为真，有攸往而自恃其强，必至阳气消尽，不利甚矣。至人于此，有抑阴扶阳之道，不使阴气消阳于尽，即于此一点阳气未尽处，顺而止之，黜聪毁智，紧闭灵窍，以为返本还元之基。</p><p>盖不能使阳而不阴者，天地循环之气机；而能于阴中保阳者，圣人逆运之功力。特以圣人有先天而天弗违之道，能以夺造化、转生杀也。至于一切常人，顺行造化，以阴剥阳，阳气消尽，化为纯阴，不死岂能之乎?</p><p>圣人于剥之一卦，直彖曰：“不利有攸往。”凡惜性命者，可以早悟矣。</p><p>初六，一阴潜生，自下消阳，如剥床以足也。床足之剥，其气虽微，其害最大，蔑贞之凶，即于此始。此阴气方进之剥也。</p><p>六二，阴气浸长，自下而上，如剥床以辨也。辨下是足，辨上是床，阴气渐升，将上于床，与阳争权，蔑贞之凶，不旋踵而至矣。此阴气渐盛之剥也。</p><p>六三，在顺体之上，不顺阴而顺阳，与阳相应，乃安静之阴，虽在剥时可以无咎。此阴气顺止之剥也。</p><p>六四，阴气结聚，顺升而上，六阳已剥去四阳，阴盛阳弱，上床用事，乃切近之灾，如剥床以肤，凶之至矣。此阴气用事之剥也。</p><p>六五，在止体之中，与阳相亲，乃客气中发现之真阴。真阴现象，不但不伤于阳，而且能统群阴，皆顺其阳。以物取之，如一鱼前领，而群鱼贯后；以人取之，如后以众宫人进宠于君王。知之者，借真阴以保真阳，则一真百真。剥者不剥，吉无不利，信有然者。此阴气顺阳无剥也。</p><p>上九，在剥之终，诸阳剥去，尚留一阳，犹未剥尽，知之者顺而止之，不为群阴所伤，如硕果不食也。果中有仁，存此一仁则生，失此一仁则死，生之死之，只在此一仁得失之间。但此一仁，庶民去之，君子存之。盖君子知此一仁为生生化化之本，保之守之。不但阴气不能伤，而且借阴以全阳，如得其舆，安而行之。至于一切小人，顺其所欲，知进而不知退，消阳至尽，终归大化，如剥其庐，自失所庇矣。此圣功能止其剥也。</p><p>六爻之剥，阴伤阳者凶，阴顺阳者吉。修道者可不顺而止之，以保其阳乎?顺而止之，颠倒之间，剥即变复，人能知剥中藏复，于此一阳未尽处下手，则后天中返先天之道得矣。噫!此天机也，知之者能有几人哉!</p>',26)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
